INSERT OR REPLACE INTO "char_abilities" VALUES(1400000201,3,2023201,'(系列条件)支援防御 LV1','[{"tid":202320101,"trait_id":202320101,"trait":{"id":202320101,"trait_type":52,"trait_value":1,"desc":"搭乘单位含有「机动战士高达AGE」系列时，\n「支援防御」+1次","action_timing":0,"tlimit":0,"active_condition_set_id":1000465,"target_condition_set_id":1000001,"value_source_condition_set_id":0,"target_weapon_condition_id":0,"use_battle_animation":false,"battle_power_value_rate_percent":1,"trait_boost_condition_set_id":0,"active_condition":{"id":1000465,"trait_condition_set_id":1000465,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"4000","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":{"id":4000,"world_id":1,"name":"机动战士高达AGE","desc":"宇宙时代，人类开始移民到宇宙殖民地已过了数百年……\n争夺霸权的战争也已结束，正当众人以为和平终于降临地球圈时，这希望又虚幻的消逝。\n由于突然出现身分不明的敌人「UE」，造成宇宙殖民地之一的「天使」崩毁……\n这巨大悲剧，之后被称为「天使之落日」。\n而之后UE跟地球联邦军的战斗也日渐加剧，菲利特‧明日野也被战火波及失去母亲。\n在母亲将明日野家代代相传的记忆单元「AGE装置」托付给菲利特后，菲利特下定决心要以装置内的设计图为基础，做出过去被称为救世主的古代MS「高达」。\n如今，跨越百年三代人的「高达」的故事，在此开幕……","icon":"series_4000","sort":850,"schedule_id":0,"scenario_stage_series_id":4000,"scenario":null,"scenarios":null,"scenario_stages":null},"character_series":null,"character_tags":null},"target_condition":{"id":1000001,"trait_condition_set_id":1000001,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":null,"character_series":null,"character_tags":null},"trait_boost":null,"granted_trait_set":null}}]');
